js='''const menu=document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=document.querySelector('.nav').classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.textContent=open?'Close':'Menu';});if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('motion');const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));}const form=document.getElementById('inquiry');if(form){const chosen=new URLSearchParams(location.search).get('package');if(['Essential','Standard','Comprehensive'].includes(chosen))form.elements.package.value=chosen;let fileUrl;form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);const text='AIKing Solutions — Introductory inquiry\\n\\n'+[...data].map(([k,v])=>k[0].toUpperCase()+k.slice(1)+': '+v).join('\\n\\n');if(fileUrl)URL.revokeObjectURL(fileUrl);fileUrl=URL.createObjectURL(new Blob([text],{type:'text/plain'}));document.getElementById('download-inquiry').href=fileUrl;document.getElementById('form-result').hidden=false;document.getElementById('form-result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});});}'''
js += """
const readiness=document.querySelectorAll('#readiness-checks input');if(readiness.length){readiness.forEach(input=>input.addEventListener('change',()=>{const checked=[...readiness].filter(i=>i.checked).length;document.getElementById('readiness-count').textContent=checked+' of 6 areas confirmed';document.getElementById('readiness-message').textContent=checked===6?'These areas are marked as in place. An independent assessment can review evidence and identify gaps beyond this introductory checklist.':(6-checked)+' areas remain unconfirmed. Bring these into your readiness discussion; a selected area still needs evidence to establish its effectiveness.';}));}
"""
