 p.joinpath(file).write_text('<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+title+' — AIKing Solutions</title><meta name="description" content="Expert-led DPDP compliance services for banks. Bank-specific assessments, policies, training and editable compliance toolkits from AIKing Solutions."><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="styles.css"><script defer src="script.js"></script></head><body>'+header+'<main>'+body+'</main>'+footer+'</body></html>')
